public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list representation of the maze
    List<List<Integer>> adjacencyList = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adjacencyList.add(new ArrayList<>());
    }
    for (int[] path : paths) {
        adjacencyList.get(path[0]).add(path[1]);
        adjacencyList.get(path[1]).add(path[0]);
    }

    // Arrays to keep track of visited nodes
    boolean[] visited = new boolean[n];
    boolean[] recStack = new boolean[n];

    // Helper function to perform DFS and detect cycles
    boolean isCyclicUtil(int node, boolean[] visited, boolean[] recStack) {
        if (recStack[node]) {
            return true;
        }
        if (visited[node]) {
            return false;
        }

        visited[node] = true;
        recStack[node] = true;

        List<Integer> children = adjacencyList.get(node);
        for (int child : children) {
            if (isCyclicUtil(child, visited, recStack)) {
                return true;
            }
        }

        recStack[node] = false;
        return false;
    }

    // Check for cycles in the maze
    for (int i = 0; i < n; i++) {
        if (isCyclicUtil(i, visited, recStack)) {
            return "cannot be travelled";
        }
    }

    // Perform BFS to check if the end is reachable from the start
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0]);
    visited = new boolean[n];
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();

        if (current == end[0]) {
            return "can be travelled";
        }

        for (int neighbor : adjacencyList.get(current)) {
            if (!visited[neighbor]) {
                queue.add(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    return "cannot be travelled";
}

