    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (helper(nums, i, sum * i / n, 0, 0)) {
                return true;
            }
        }
    }
    return false;
}

private boolean helper(int[] nums, int targetSize, int targetSum, int index, int currentSum) {
    if (targetSize == 0 && targetSum == 0) {
        return true;
    }
    if (targetSize == 0 || targetSum == 0 || index >= nums.length) {
        return false;
    }
    return helper(nums, targetSize - 1, targetSum - nums[index], index + 1, currentSum + nums[index]) ||
           helper(nums, targetSize, targetSum, index + 1, currentSum);
}

