public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance += 1;
        } else {
            balance -= 1;
            if (i < s.length() - 1 && s.charAt(i + 1) == ')') {
                i += 1;
            } else {
                insertions += 1;
            }
        }
        if (balance < 0) {
            insertions += 1;
            balance += 1;
        }
    }

    return insertions + balance * 2;
}

