private static boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

private static void permute(int[] A, boolean[] visited, int start, int count) {
        if (start == A.length - 1) {
            count++;
            return;
        }

        for (int i = start; i < A.length; i++) {
            if (!visited[i]) {
                visited[i] = true;
                if (start == 0 || isPerfectSquare(A[start - 1] + A[i])) {
                    permute(A, visited, start + 1, count);
                }
                visited[i] = false;
            }
        }
    }

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? -1 : heights[i];

        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];
        if ((row + col) % 2 == 0) {
            if (col == n - 1) {
                row++;
            } else if (row == 0) {
                col++;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == m - 1) {
                col++;
            } else if (col == 0) {
                row++;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Start from the end and find the first digit that is smaller than the digit next to it
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of (i)th digit that is greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }

            // Swap the found digits
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the (i)th position
            Arrays.sort(digits, i + 1, len);

            // Return the new number
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
